<?= view('partials/header', ['title' => $title]) ?>
<?php $validation = service('validation'); ?>
<p class="eyebrow">User form</p><h1><?= $user ? 'Edit user' : 'New user' ?></h1><p class="lead">Usernames must be unique. JPG and PNG avatars are limited to 2MB.</p>
<?php if ($validation->getErrors()): ?><div class="alert error"><?php foreach ($validation->getErrors() as $error): ?><div><?= esc($error) ?></div><?php endforeach; ?></div><?php endif; ?><?php if (session()->getFlashdata('error')): ?><div class="alert error"><?= esc(session()->getFlashdata('error')) ?></div><?php endif; ?>
<section class="card"><form class="form-grid" method="post" action="" enctype="multipart/form-data"><input type="hidden" name="<?= csrf_token() ?>" value="<?= csrf_hash() ?>">
<div class="field"><label for="username">Username</label><input id="username" name="username" value="<?= esc(old('username', $user['username'] ?? '')) ?>" required><?php if ($validation->hasError('username')): ?><span class="error"><?= esc($validation->getError('username')) ?></span><?php endif; ?></div>
<div class="field"><label for="full_name">Full name</label><input id="full_name" name="full_name" value="<?= esc(old('full_name', $user['full_name'] ?? '')) ?>" required><?php if ($validation->hasError('full_name')): ?><span class="error"><?= esc($validation->getError('full_name')) ?></span><?php endif; ?></div>
<div class="field"><label for="email">Email</label><input id="email" type="email" name="email" value="<?= esc(old('email', $user['email'] ?? '')) ?>" required><?php if ($validation->hasError('email')): ?><span class="error"><?= esc($validation->getError('email')) ?></span><?php endif; ?></div>
<div class="field"><label for="avatar">Profile picture <small>(JPG/PNG, max 2MB)</small></label><input id="avatar" type="file" name="avatar" accept="image/jpeg,image/png"><?php if ($validation->hasError('avatar')): ?><span class="error"><?= esc($validation->getError('avatar')) ?></span><?php endif; ?></div>
<div><button class="button" type="submit">Save user</button> <a class="button secondary" href="<?= base_url('users') ?>">Cancel</a></div></form></section><?= view('partials/footer') ?>
